arguments.command:
KUBECONFIG=/tmp/kubeconfig kubectl patch deploy product-catalog -n astronomy-shop --type=json -p='[
  {
    "op": "add",
    "path": "/spec/template/spec/initContainers",
    "value": [
      {
        "name": "wait-for-postgresql",
        "image": "busybox:latest",
        "imagePullPolicy": "IfNotPresent",
        "command": ["sh", "-c", "until nc -z -v -w5 postgresql 5432; do echo waiting for postgresql; sleep 2; done;"]
      }
    ]
  }
]'
